-- Public questions and answers on each listing (SHCWS-57). Additive and re-runnable.
-- Requires db/founder-solutions.sql, db/auth.sql and db/listing-notices.sql.
--
-- Anyone with a verified email asks in public under an alias; only the listing's owner
-- answers, and the answer is shown as theirs. The owner can never ask on their own
-- listing, nor edit or delete someone else's question (the rule §46 set for comments):
-- they can report it. Only ops hides a question, with a reason its author reads.
CREATE TABLE IF NOT EXISTS solution_questions (
  -- Generated by the client: a retried submit returns the same row instead of a second one.
  id uuid PRIMARY KEY,
  solution_id uuid NOT NULL REFERENCES founder_solutions(id) ON DELETE CASCADE,
  author_id uuid NOT NULL REFERENCES auth_accounts(id) ON DELETE CASCADE,
  author_name varchar(60) NOT NULL CHECK (char_length(btrim(author_name)) > 0),
  body varchar(500) NOT NULL CHECK (char_length(btrim(body)) >= 10),
  answer varchar(2000) CHECK (answer IS NULL OR char_length(btrim(answer)) > 0),
  answered_at timestamptz,
  hidden_at timestamptz,
  hidden_reason varchar(500),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((answer IS NULL) = (answered_at IS NULL)),
  CHECK ((hidden_at IS NULL) = (hidden_reason IS NULL))
);
CREATE INDEX IF NOT EXISTS solution_questions_solution
  ON solution_questions (solution_id, created_at DESC, id);
CREATE INDEX IF NOT EXISTS solution_questions_author ON solution_questions (author_id);

-- Reports, mirroring solution_comment_reports. question_id is SET NULL, not CASCADE: a
-- question its author deletes keeps the record of how its report was decided.
CREATE TABLE IF NOT EXISTS solution_question_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_id uuid REFERENCES solution_questions(id) ON DELETE SET NULL,
  solution_id uuid NOT NULL REFERENCES founder_solutions(id) ON DELETE CASCADE,
  reporter_id uuid REFERENCES auth_accounts(id) ON DELETE SET NULL,
  reason text NOT NULL CHECK (reason IN ('spam', 'abuse', 'impersonation', 'other')),
  details varchar(2000) NOT NULL CHECK (char_length(btrim(details)) >= 10),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'dismissed')),
  decision varchar(2000),
  reviewer_id uuid REFERENCES auth_accounts(id) ON DELETE SET NULL,
  resolved_at timestamptz,
  version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- One open report per person and question; a retry answers 409 instead of piling up.
CREATE UNIQUE INDEX IF NOT EXISTS solution_question_reports_open
  ON solution_question_reports (question_id, reporter_id) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS solution_question_reports_status
  ON solution_question_reports (status, created_at DESC);

-- The owner hears about each new question through their listing notices: on by default,
-- only to a verified address (db/listing-notices.sql). The text goes in the email, never
-- who asked beyond the alias they chose.
CREATE OR REPLACE FUNCTION notify_solution_question() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target uuid;
BEGIN
  SELECT owner_id INTO target FROM founder_solutions WHERE id = NEW.solution_id;
  IF target IS NOT NULL AND target <> NEW.author_id THEN
    PERFORM listing_notice(target, 'question:' || NEW.id, 'Nueva pregunta sobre tu ficha',
      '/account/solutions/' || NEW.solution_id);
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS solution_question_notification ON solution_questions;
CREATE TRIGGER solution_question_notification AFTER INSERT ON solution_questions
  FOR EACH ROW EXECUTE FUNCTION notify_solution_question();
